FROM CLSR_DAY_MST
WHERE DEL_DT IS NULL

	AND USE_YN = #{useYn}


	AND CLSR_SE_CD = #{clsrSeCd}


	AND END_YMD >= #{startDate}


	AND BGNG_YMD <= #{endDate}


	AND CLSR_RESN_CN LIKE CONCAT('%', #{searchKeyword}, '%')

